document.addEventListener("DOMContentLoaded",function(){let display=document.getElementById("display"),buttons=document.querySelectorAll("button");buttons.forEach(btn=>{btn.addEventListener("click",()=>{let value=btn.textContent;if("C"===value)display.value="";else if("="===value)try{display.value=eval(display.value)}catch{display.value="Erro"}else display.value+=value})})});